class_name PluginEvaluator
extends RefCounted


func evaluate_plugin(info: Dictionary) -> Dictionary:
	var license: String = String(info.get("license", ""))
	var godot_version: String = String(info.get("godot_version", ""))
	var last_update: String = String(info.get("last_update", ""))
	var has_docs: bool = bool(info.get("has_documentation", false))

	var checks_passed: int = 0
	var reasons: Array[String] = []

	if not license.is_empty() and license != "Sconosciuta":
		checks_passed += 1
	else:
		reasons.append("Licenza non valida o sconosciuta.")

	if godot_version == "4.7":
		checks_passed += 1
	else:
		reasons.append("Versione Godot diversa da 4.7.")

	if not last_update.is_empty():
		checks_passed += 1
	else:
		reasons.append("Data ultimo aggiornamento mancante.")

	if has_docs:
		checks_passed += 1
	else:
		reasons.append("Documentazione non fornita.")

	var approved := (checks_passed == 4)

	return {
		"approved": approved,
		"checks_passed": checks_passed,
		"reasons": reasons
	}


func load_and_evaluate_register(path: String) -> Array[Dictionary]:
	var results: Array[Dictionary] = []
	if not FileAccess.file_exists(path):
		return results

	var file := FileAccess.open(path, FileAccess.READ)
	if not file:
		return results

	var content := file.get_as_text()
	var json_data: Variant = JSON.parse_string(content)
	if not json_data is Dictionary:
		return results

	var dict_data: Dictionary = json_data
	var list: Array = dict_data.get("plugins", [])

	for item in list:
		if item is Dictionary:
			results.append(evaluate_plugin(item))

	return results

