func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return

	var runner := find_by_name(main, "DialogueRunner")
	if not check("runner_node", runner != null, "La scena deve contenere il nodo DialogueRunner"):
		return

	var line0: Dictionary = call_if_exists(runner, "get_current_line", [], {})
	check("line0_speaker", line0.get("speaker", "") == "Elena", "La prima battuta deve essere di Elena (trovato: %s)" % line0.get("speaker", ""))
	check("line0_text", String(line0.get("text", "")).contains("chiusa"), "La prima battuta deve contenere il testo iniziale della storia")

	var adv1: bool = call_if_exists(runner, "advance", [], false)
	check("advance_success", adv1 == true, "advance deve restituire true quando si passa alla seconda battuta valida")

	var line1: Dictionary = call_if_exists(runner, "get_current_line", [], {})
	check("line1_speaker", line1.get("speaker", "") == "Marco", "La seconda battuta deve essere di Marco (trovato: %s)" % line1.get("speaker", ""))

	var adv2: bool = call_if_exists(runner, "advance", [], true)
	check("advance_end", adv2 == false, "advance deve restituire false quando la storia finisce")

	var line_end: Dictionary = call_if_exists(runner, "get_current_line", [], {"dummy": 1})
	check("line_empty", line_end.is_empty(), "get_current_line deve restituire un dizionario vuoto alla fine della storia")

	var reg_exists := FileAccess.file_exists("res://assets/plugin_register.json")
	check("reg_file", reg_exists, "Il file res://assets/plugin_register.json deve esistere")
	if reg_exists:
		var file := FileAccess.open("res://assets/plugin_register.json", FileAccess.READ)
		if file:
			var content := file.get_as_text()
			var json_data: Variant = JSON.parse_string(content)
			if check("reg_json", json_data is Dictionary, "Il registro deve contenere un JSON valido"):
				var dict: Dictionary = json_data
				check("reg_lic", dict.get("license", "") == "MIT", "La licenza nel registro deve essere MIT")
				check("reg_ver", dict.get("godot_version", "") == "4.7", "La versione Godot nel registro deve essere 4.7")
				check("reg_docs", bool(dict.get("has_documentation", false)) == true, "has_documentation deve essere true nel registro")

